package com.webox.common;

import java.util.LinkedHashMap;
import java.util.Map;

public final class Api {
    private Api() {}

    public static Map<String, Object> envelope(String code, String message, Object data) {
        Map<String, Object> m = new LinkedHashMap<>();
        m.put("code", code);
        m.put("message", message);
        m.put("data", data);
        m.put("requestId", RequestContext.requestId());
        return m;
    }

    public static Map<String, Object> ok(Object data) {
        return envelope("OK", "OK", data);
    }

    public static ApiException error(int status, String code, String message) {
        return new ApiException(status, code, message, null);
    }

    public static ApiException error(int status, String code, String message, Object data) {
        return new ApiException(status, code, message, data);
    }
}

package com.webox.common;

public class ApiException extends RuntimeException {
    private final int status;
    private final String code;
    private final Object data;

    public ApiException(int status, String code, String message, Object data) {
        super(message);
        this.status = status;
        this.code = code;
        this.data = data;
    }

    public int getStatus() { return status; }
    public String getCode() { return code; }
    public Object getData() { return data; }
}

package com.webox.common;

import org.slf4j.MDC;

import java.time.Instant;
import java.time.ZoneId;
import java.time.ZonedDateTime;
import java.util.UUID;

public final class RequestContext {
    public static final ZoneId ZONE = ZoneId.of("Asia/Shanghai");
    private static final ThreadLocal<Instant> TEST_CLOCK = new ThreadLocal<>();

    private RequestContext() {}

    public static String requestId() {
        String id = MDC.get("requestId");
        return id == null ? UUID.randomUUID().toString() : id;
    }

    public static void setTestClock(Instant instant) { TEST_CLOCK.set(instant); }
    public static void clearTestClock() { TEST_CLOCK.remove(); }
    public static boolean hasTestClock() { return TEST_CLOCK.get() != null; }

    public static ZonedDateTime now() {
        Instant i = TEST_CLOCK.get();
        return (i == null ? Instant.now() : i).atZone(ZONE);
    }

    public static java.time.LocalDate today() { return now().toLocalDate(); }
}

package com.webox.common;

import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.MDC;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.core.Ordered;
import org.springframework.core.annotation.Order;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.time.OffsetDateTime;
import java.time.format.DateTimeParseException;
import java.util.UUID;

@Component
@Order(Ordered.HIGHEST_PRECEDENCE)
public class RequestIdFilter extends OncePerRequestFilter {
    @Value("${spring.profiles.active:default}")
    private String activeProfile;

    @Value("${webox.test.clock-enabled:false}")
    private boolean clockEnabled;

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        String rid = UUID.randomUUID().toString();
        MDC.put("requestId", rid);
        res.setHeader("X-Request-Id", rid);
        res.setHeader("Access-Control-Expose-Headers", "X-Request-Id");
        try {
            String clock = req.getHeader("X-Test-Clock");
            if (clock != null && !clock.isBlank()) {
                boolean testProfile = activeProfile != null && activeProfile.contains("test");
                if (!testProfile || !clockEnabled) {
                    writeError(res, 400, "VALIDATION_TEST_CLOCK_FORBIDDEN",
                            "X-Test-Clock is only allowed in test profile");
                    return;
                }
                try {
                    RequestContext.setTestClock(OffsetDateTime.parse(clock).toInstant());
                } catch (DateTimeParseException e) {
                    writeError(res, 400, "VALIDATION_TEST_CLOCK_FORBIDDEN", "Invalid X-Test-Clock value");
                    return;
                }
            }
            chain.doFilter(req, res);
        } finally {
            RequestContext.clearTestClock();
            MDC.remove("requestId");
        }
    }

    private void writeError(HttpServletResponse res, int status, String code, String msg) throws IOException {
        res.setStatus(status);
        res.setContentType("application/json;charset=UTF-8");
        res.getWriter().write("{\"code\":\"" + code + "\",\"message\":\"" + msg +
                "\",\"data\":null,\"requestId\":\"" + RequestContext.requestId() + "\"}");
    }
}

package com.webox.common;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataAccessException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.MissingServletRequestParameterException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;
import org.springframework.web.multipart.MaxUploadSizeExceededException;

import java.util.Map;

@RestControllerAdvice
public class GlobalExceptionHandler {
    private static final Logger log = LoggerFactory.getLogger(GlobalExceptionHandler.class);

    @ExceptionHandler(ApiException.class)
    public ResponseEntity<Map<String, Object>> api(ApiException e) {
        return ResponseEntity.status(e.getStatus())
                .body(Api.envelope(e.getCode(), e.getMessage(), e.getData()));
    }

    @ExceptionHandler(MethodArgumentNotValidException.class)
    public ResponseEntity<Map<String, Object>> validation(MethodArgumentNotValidException e) {
        String field = e.getBindingResult().getFieldError() == null ? "" : e.getBindingResult().getFieldError().getField();
        String code = switch (field) {
            case "email" -> "VALIDATION_EMAIL_FORMAT";
            case "password" -> "VALIDATION_PASSWORD_POLICY";
            case "address" -> "VALIDATION_ADDRESS_LENGTH";
            case "search" -> "VALIDATION_SEARCH_LENGTH";
            case "reason" -> "VALIDATION_REASON_REQUIRED";
            case "qty" -> "VALIDATION_QUANTITY";
            default -> "VALIDATION_INVALID";
        };
        String msg = e.getBindingResult().getFieldError() == null ? "Validation failed"
                : e.getBindingResult().getFieldError().getDefaultMessage();
        return ResponseEntity.badRequest().body(Api.envelope(code, msg, null));
    }

    @ExceptionHandler({HttpMessageNotReadableException.class, MethodArgumentTypeMismatchException.class,
            MissingServletRequestParameterException.class})
    public ResponseEntity<Map<String, Object>> badRequest(Exception e) {
        return ResponseEntity.badRequest().body(Api.envelope("VALIDATION_INVALID", "Invalid request", null));
    }

    @ExceptionHandler(MaxUploadSizeExceededException.class)
    public ResponseEntity<Map<String, Object>> tooLarge(MaxUploadSizeExceededException e) {
        return ResponseEntity.badRequest().body(Api.envelope("VALIDATION_IMAGE", "Image must be at most 5MB", null));
    }

    @ExceptionHandler(DataAccessException.class)
    public ResponseEntity<Map<String, Object>> data(DataAccessException e) {
        log.error("Database error", e);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Api.envelope("INTERNAL", "Internal server error", null));
    }

    @ExceptionHandler(Exception.class)
    public ResponseEntity<Map<String, Object>> other(Exception e) {
        log.error("Unhandled error", e);
        return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR)
                .body(Api.envelope("INTERNAL", "Internal server error", null));
    }
}

