package com.webox.security;

import com.fasterxml.jackson.databind.ObjectMapper;
import com.webox.common.Api;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

import javax.crypto.Mac;
import javax.crypto.spec.SecretKeySpec;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.SecureRandom;
import java.util.Base64;
import java.util.LinkedHashMap;
import java.util.Map;

@Service
public class JwtService {
    private static final Logger log = LoggerFactory.getLogger(JwtService.class);
    private static final Base64.Encoder B64 = Base64.getUrlEncoder().withoutPadding();
    private static final Base64.Decoder B64D = Base64.getUrlDecoder();

    private final byte[] secret;
    private final ObjectMapper mapper;
    private final long accessTtl;

    public JwtService(@Value("${webox.jwt.[REDACTED CREDENTIAL] String configuredSecret,
                      @Value("${webox.jwt.access-ttl-seconds:7200}") long accessTtl,
                      ObjectMapper mapper) {
        this.mapper = mapper;
        this.accessTtl = accessTtl;
        if (configured[REDACTED CREDENTIAL] null || configuredSecret.isBlank()) {
            byte[] r = new byte[32];
            new SecureRandom().nextBytes(r);
            this.[REDACTED CREDENTIAL]            log.warn("JWT_SECRET not set; using an ephemeral random key (tokens invalid after restart)");
        } else {
            this.[REDACTED CREDENTIAL]        }
    }

    public long accessTtlSeconds() { return accessTtl; }

    public String issue(UserPrincipal p) {
        long now = System.currentTimeMillis() / 1000;
        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("sub", String.valueOf(p.id()));
        payload.put("email", p.email());
        payload.put("role", p.role());
        payload.put("iat", now);
        payload.put("exp", now + accessTtl);
        try {
            String header = B64.encodeToString("{\"alg\":\"HS256\",\"typ\":\"JWT\"}".getBytes(StandardCharsets.UTF_8));
            String body = B64.encodeToString(mapper.writeValueAsBytes(payload));
            String sig = B64.encodeToString(hmac(header + "." + body));
            return header + "." + body + "." + sig;
        } catch (Exception e) {
            throw new IllegalStateException("JWT signing failed", e);
        }
    }

    public UserPrincipal parse(String token) {
        try {
            String[] parts = token.split("\\.");
            if (parts.length != 3) throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid token");
            byte[] expected = hmac(parts[0] + "." + parts[1]);
            byte[] actual = B64D.decode(parts[2]);
            if (!MessageDigest.isEqual(expected, actual)) {
                throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid token");
            }
            Map<?, ?> payload = mapper.readValue(B64D.decode(parts[1]), Map.class);
            long exp = ((Number) payload.get("exp")).longValue();
            if (System.currentTimeMillis() / 1000 >= exp) {
                throw Api.error(401, "AUTH_TOKEN_INVALID", "Token expired");
            }
            return new UserPrincipal(Long.parseLong(String.valueOf(payload.get("sub"))),
                    String.valueOf(payload.get("email")), String.valueOf(payload.get("role")));
        } catch (ApiException e) {
            throw e;
        } catch (Exception e) {
            throw Api.error(401, "AUTH_TOKEN_INVALID", "Invalid token");
        }
    }

    private byte[] hmac(String data) throws Exception {
        Mac mac = Mac.getInstance("HmacSHA256");
        mac.init(new SecretKeySpec(secret, "HmacSHA256"));
        return mac.doFinal(data.getBytes(StandardCharsets.UTF_8));
    }
}

package com.webox.security;

import com.webox.common.ApiException;
import jakarta.servlet.FilterChain;
import jakarta.servlet.ServletException;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import org.slf4j.MDC;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.security.core.context.SecurityContextHolder;
import org.springframework.stereotype.Component;
import org.springframework.web.filter.OncePerRequestFilter;

import java.io.IOException;
import java.util.List;

@Component
public class JwtFilter extends OncePerRequestFilter {
    private final JwtService jwtService;

    public JwtFilter(JwtService jwtService) {
        this.jwtService = jwtService;
    }

    @Override
    protected void doFilterInternal(HttpServletRequest req, HttpServletResponse res, FilterChain chain)
            throws ServletException, IOException {
        String header = req.getHeader("Authorization");
        if (header != null && header.startsWith("Bearer ")) {
            try {
                UserPrincipal p = jwtService.parse(header.substring(7).trim());
                UsernamePasswordAuthenticationToken auth = new UsernamePasswordAuthenticationToken(
                        p, null, List.of(new SimpleGrantedAuthority("ROLE_" + p.role())));
                SecurityContextHolder.getContext().setAuthentication(auth);
                MDC.put("userId", String.valueOf(p.id()));
            } catch (ApiException e) {
                res.setStatus(401);
                res.setContentType("application/json;charset=UTF-8");
                res.getWriter().write("{\"code\":\"" + e.getCode() + "\",\"message\":\"" + e.getMessage()
                        + "\",\"data\":null,\"requestId\":\"" + MDC.get("requestId") + "\"}");
                return;
            }
        }
        try {
            chain.doFilter(req, res);
        } finally {
            MDC.remove("userId");
        }
    }
}

package com.webox.config;

import com.webox.common.Api;
import com.webox.security.JwtFilter;
import com.webox.security.UserPrincipal;
import jakarta.servlet.http.HttpServletResponse;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.security.config.annotation.web.builders.HttpSecurity;
import org.springframework.security.config.http.SessionCreationPolicy;
import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
import org.springframework.security.crypto.password.PasswordEncoder;
import org.springframework.security.web.SecurityFilterChain;
import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
import org.springframework.web.cors.CorsConfiguration;
import org.springframework.web.cors.CorsConfigurationSource;
import org.springframework.web.cors.UrlBasedCorsConfigurationSource;

import java.util.List;

@Configuration
public class SecurityConfig {
    private final JwtFilter jwtFilter;

    public SecurityConfig(JwtFilter jwtFilter) {
        this.jwtFilter = jwtFilter;
    }

    @Bean
    public PasswordEncoder passwordEncoder() {
        return new BCryptPasswordEncoder(10);
    }

    @Bean
    public SecurityFilterChain filterChain(HttpSecurity http,
                                           @Value("${webox.cors.allowed-origin:http://127.0.0.1:5173}") String origin) throws Exception {
        http.csrf(csrf -> csrf.disable())
                .cors(c -> c.configurationSource(corsSource(origin)))
                .sessionManagement(s -> s.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
                .authorizeHttpRequests(a -> a
                        .requestMatchers("/api/v1/auth/register", "/api/v1/auth/login", "/api/v1/auth/refresh",
                                "/api/v1/health", "/api/v1/menu/stream", "/images/**", "/error").permitAll()
                        .requestMatchers("/api/v1/admin/**").hasRole("ADMIN")
                        .anyRequest().authenticated())
                .exceptionHandling(e -> e
                        .authenticationEntryPoint((req, res, ex) -> write(res, 401, "AUTH_UNAUTHORIZED", "Authentication required"))
                        .accessDeniedHandler((req, res, ex) -> write(res, 403, "FORBIDDEN", "Access denied")))
                .addFilterBefore(jwtFilter, UsernamePasswordAuthenticationFilter.class);
        return http.build();
    }

    private void write(HttpServletResponse res, int status, String code, String msg) throws java.io.IOException {
        res.setStatus(status);
        res.setContentType("application/json;charset=UTF-8");
        res.getWriter().write("{\"code\":\"" + code + "\",\"message\":\"" + msg
                + "\",\"data\":null,\"requestId\":\"" + com.webox.common.RequestContext.requestId() + "\"}");
    }

    private CorsConfigurationSource corsSource(String origin) {
        CorsConfiguration c = new CorsConfiguration();
        c.setAllowedOrigins(List.of(origin, "http://localhost:5173", "http://127.0.0.1:5173"));
        c.setAllowedMethods(List.of("GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"));
        c.setAllowedHeaders(List.of("Authorization", "Idempotency-Key", "Content-Type", "X-Test-Clock", "Accept"));
        c.setExposedHeaders(List.of("X-Request-Id"));
        c.setAllowCredentials(true);
        c.setMaxAge(3600L);
        UrlBasedCorsConfigurationSource s = new UrlBasedCorsConfigurationSource();
        s.registerCorsConfiguration("/**", c);
        return s;
    }

    public static UserPrincipal current() {
        var auth = org.springframework.security.core.context.SecurityContextHolder.getContext().getAuthentication();
        if (auth == null || !(auth.getPrincipal() instanceof UserPrincipal p)) {
            throw Api.error(401, "AUTH_UNAUTHORIZED", "Authentication required");
        }
        return p;
    }
}

