                            Integer rollbackToVersion) {}

    public record AiReq(@Size(max = 500) String prompt, String sessionId) {}

    public record FilterDates(String date, boolean published) {}
}

package com.webox.inventory;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

import java.io.BufferedInputStream;
import java.io.BufferedOutputStream;
import java.io.InputStream;
import java.io.OutputStream;
import java.net.InetSocketAddress;
import java.net.Socket;
import java.nio.charset.StandardCharsets;

/**
 * Minimal RESP (Redis protocol) client. Kept dependency-free so that Redis remains optional
 * and any connectivity failure can be handled as a graceful degradation by callers.
 */
@Component
public class RedisClient {
    private final boolean enabled;
    private final String host;
    private final int port;
    private final int timeoutMs;

    public RedisClient(@Value("${webox.redis.enabled:true}") boolean enabled,
                       @Value("${webox.redis.host:127.0.0.1}") String host,
                       @Value("${webox.redis.port:6379}") int port,
                       @Value("${webox.redis.timeout-ms:300}") int timeoutMs) {
        this.enabled = enabled;
        this.host = host;
        this.port = port;
        this.timeoutMs = timeoutMs;
    }

    public boolean enabled() { return enabled; }

    public boolean ping() {
        if (!enabled) return false;
        try {
            Object r = command("PING");
            return "PONG".equals(String.valueOf(r));
        } catch (Exception e) {
            return false;
        }
    }

    public String get(String key) {
        Object r = command("GET", key);
        return r == null ? null : String.valueOf(r);
    }

    public void set(String key, String value, int ttlSeconds) {
        command("SET", key, value, "EX", String.valueOf(ttlSeconds));
    }

    public long decrBy(String key, long n) {
        Object r = command("DECRBY", key, String.valueOf(n));
        return ((Number) r).longValue();
    }

    public long incrBy(String key, long n) {
        Object r = command("INCRBY", key, String.valueOf(n));
        return ((Number) r).longValue();
    }

    /** Lua preallocation: returns 1 ok, 0 insufficient, -1 key missing. */
    public long prealloc(String key, long qty) {
        String lua = "local v=tonumber(redis.call('GET',KEYS[1]) or '-1') "
                + "if v<0 then return -1 end "
                + "if v<tonumber(ARGV[1]) then return 0 end "
                + "redis.call('DECRBY',KEYS[1],ARGV[1]) return 1";
        Object r = command("EVAL", lua, "1", key, String.valueOf(qty));
        return ((Number) r).longValue();
    }

    public Object command(String... args) {
        if (!enabled) throw new IllegalStateException("redis disabled");
        try (Socket socket = new Socket()) {
            socket.connect(new InetSocketAddress(host, port), timeoutMs);
            socket.setSoTimeout(timeoutMs);
            OutputStream out = new BufferedOutputStream(socket.getOutputStream());
            StringBuilder sb = new StringBuilder("*").append(args.length).append("\r\n");
            for (String a : args) {
                byte[] b = a.getBytes(StandardCharsets.UTF_8);
                sb.append("$").append(b.length).append("\r\n").append(a).append("\r\n");
            }
            out.write(sb.toString().getBytes(StandardCharsets.UTF_8));
            out.flush();
            InputStream in = new BufferedInputStream(socket.getInputStream());
            return read(in);
        } catch (Exception e) {
            throw new IllegalStateException("redis command failed: " + e.getMessage(), e);
        }
    }

    private Object read(InputStream in) throws Exception {
        int type = in.read();
        if (type < 0) throw new IllegalStateException("empty redis response");
        String line = readLine(in);
        switch (type) {
            case '+': return line;
            case '-': throw new IllegalStateException("redis error: " + line);
            case ':': return Long.parseLong(line);
            case '$': {
                int len = Integer.parseInt(line);
                if (len < 0) return null;
                byte[] buf = in.readNBytes(len);
                readLine(in);
                return new String(buf, StandardCharsets.UTF_8);
            }
            case '*': {
                int n = Integer.parseInt(line);
                if (n < 0) return null;
                Object[] arr = new Object[n];
                for (int i = 0; i < n; i++) arr[i] = read(in);
                return arr;
            }
            default: throw new IllegalStateException("unknown redis reply type " + type);
        }
    }

    private String readLine(InputStream in) throws Exception {
        StringBuilder sb = new StringBuilder();
        int c;
        while ((c = in.read()) != -1) {
            if (c == '\r') {
                int n = in.read();
                if (n == '\n') break;
                sb.append((char) c).append((char) n);
            } else {
                sb.append((char) c);
            }
        }
        return sb.toString();
    }
}

package com.webox.config;

import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationArguments;
import org.springframework.boot.ApplicationRunner;
import org.springframework.core.io.ClassPathResource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Component;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.List;

/** Creates the 17-table schema and seed data on first start (idempotent). */
@Component
public class DbBootstrap implements ApplicationRunner {
    private static final Logger log = LoggerFactory.getLogger(DbBootstrap.class);
    private final JdbcTemplate jdbc;

    public DbBootstrap(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public void run(ApplicationArguments args) throws Exception {
        Integer tables = jdbc.queryForObject(
                "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema=DATABASE() AND table_name='users'",
                Integer.class);
        if (tables != null && tables > 0) {
            log.info("Database schema present; skipping bootstrap");
            return;
        }
        String sql = new String(new ClassPathResource("db/schema.sql").getInputStream().readAllBytes(),
                StandardCharsets.UTF_8);
        List<String> statements = split(sql);
        log.info("Bootstrapping database with {} statements", statements.size());
        for (String s : statements) {
            if (!s.isBlank()) jdbc.execute(s);
        }
        log.info("Database bootstrap complete");
    }

    private List<String> split(String sql) {
        StringBuilder cleaned = new StringBuilder();
        for (String line : sql.split("\n")) {
            String t = line.stripLeading();
            if (t.startsWith("--") || t.startsWith("SET ") || t.isBlank()) continue;
            cleaned.append(line).append('\n');
        }
        List<String> out = new ArrayList<>();
        StringBuilder cur = new StringBuilder();
        boolean inSingle = false;
        char[] chars = cleaned.toString().toCharArray();
        for (int i = 0; i < chars.length; i++) {
            char c = chars[i];
            if (c == '\'' ) {
                boolean escaped = i > 0 && chars[i - 1] == '\\';
                if (!escaped) inSingle = !inSingle;
            }
            if (c == ';' && !inSingle) {
                out.add(cur.toString().trim());
                cur.setLength(0);
            } else {
                cur.append(c);
            }
        }
        if (!cur.toString().isBlank()) out.add(cur.toString().trim());
        return out;
    }
}

package com.webox.common;

import org.springframework.stereotype.Component;

import java.util.ArrayDeque;
import java.util.Deque;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

/** In-memory sliding-window limiter (single instance demo). */
@Component
public class RateLimiter {
    private final Map<String, Deque<Long>> hits = new ConcurrentHashMap<>();

    public void check(String key, int limit, long windowMs) {
        long now = System.currentTimeMillis();
        Deque<Long> q = hits.computeIfAbsent(key, k -> new ArrayDeque<>());
        synchronized (q) {
            while (!q.isEmpty() && now - q.peekFirst() > windowMs) q.pollFirst();
            if (q.size() >= limit) throw Api.error(429, "RATE_LIMITED", "Too many requests");
            q.addLast(now);
        }
    }
}

package com.webox.auth;

import com.webox.common.Api;
import com.webox.common.RateLimiter;
