    private void checkPassword(String p) {
        if (p == null || p.length() < 8 || p.length() > 64
                || !p.chars().anyMatch(Character::isLetter) || !p.chars().anyMatch(Character::isDigit)) {
            throw Api.error(400, "VALIDATION_PASSWORD_POLICY",
