package com.webox.auth;

import com.webox.common.Api;
import com.webox.config.SecurityConfig;
import com.webox.dto.Dtos;
import jakarta.servlet.http.HttpServletRequest;
import jakarta.validation.Valid;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;

import java.util.Map;

@RestController
@RequestMapping("/api/v1")
public class AuthController {
    private final AuthService authService;

    public AuthController(AuthService authService) {
        this.authService = authService;
    }

    @PostMapping("/auth/register")
    public ResponseEntity<Map<String, Object>> register(@Valid @RequestBody Dtos.RegisterReq req) {
        return ResponseEntity.status(HttpStatus.CREATED).body(Api.ok(authService.register(req)));
    }

    @PostMapping("/auth/login")
    public Map<String, Object> login(@Valid @RequestBody Dtos.LoginReq req, HttpServletRequest request) {
        String ip = request.getRemoteAddr();
        return Api.ok(authService.login(req, ip));
    }

    @PostMapping("/auth/refresh")
    public Map<String, Object> refresh(@Valid @RequestBody Dtos.RefreshReq req) {
        return Api.ok(authService.refresh(req));
    }

    @PostMapping("/auth/logout")
    public Map<String, Object> logout(@Valid @RequestBody Dtos.RefreshReq req) {
        SecurityConfig.current();
        return Api.ok(authService.logout(req));
    }

    @GetMapping("/auth/me")
    public Map<String, Object> me() {
        return Api.ok(authService.me(SecurityConfig.current().id()));
    }
}

package com.webox.auth;

import com.webox.common.Api;
import com.webox.common.Util;
import com.webox.config.SecurityConfig;
import com.webox.dto.Dtos;
import jakarta.validation.Valid;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.bind.annotation.*;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@RestController
@RequestMapping("/api/v1/me")
public class MeController {
    private final JdbcTemplate jdbc;

    public MeController(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    @GetMapping("/preferences")
    public Map<String, Object> getPreferences() {
        long uid = SecurityConfig.current().id();
        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM user_preferences WHERE user_id=?", uid);
        Map<String, Object> data = new LinkedHashMap<>();
        if (rows.isEmpty()) {
            data.put("allergens", List.of());
            data.put("preferredCategories", List.of());
            data.put("spicePreference", null);
            data.put("tastePreference", null);
            data.put("budgetMinCents", null);
            data.put("budgetMaxCents", null);
            data.put("recommendEnabled", false);
            return Api.ok(data);
        }
        Map<String, Object> r = rows.get(0);
        data.put("allergens", Util.parseList((String) r.get("allergens")));
        data.put("preferredCategories", Util.parseList((String) r.get("preferred_categories")));
        data.put("spicePreference", r.get("spice_preference"));
        data.put("tastePreference", r.get("taste_preference"));
        data.put("budgetMinCents", r.get("budget_min_cents"));
        data.put("budgetMaxCents", r.get("budget_max_cents"));
        data.put("recommendEnabled", ((Number) r.get("recommend_enabled")).intValue() == 1);
        return Api.ok(data);
    }

    @PutMapping("/preferences")
    public Map<String, Object> putPreferences(@RequestBody Dtos.PrefReq req) {
        long uid = SecurityConfig.current().id();
        List<String> allergens = req.allergens() == null ? List.of() : req.allergens();
        List<String> categories = req.preferredCategories() == null ? List.of() : req.preferredCategories();
        for (String a : allergens) {
            if (!Util.ALLERGENS.contains(a)) throw Api.error(400, "VALIDATION_CATEGORY", "Invalid allergen: " + a);
        }
        for (String c : categories) {
            if (!Util.CATEGORIES.contains(c)) throw Api.error(400, "VALIDATION_CATEGORY", "Invalid category: " + c);
        }
        if (req.spicePreference() != null && !Util.SPICE.contains(req.spicePreference())) {
            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid spice preference");
        }
        if (req.tastePreference() != null && !List.of("Light", "Medium", "Rich").contains(req.tastePreference())) {
            throw Api.error(400, "VALIDATION_CATEGORY", "Invalid taste preference");
        }
        if (req.budgetMinCents() != null && req.budgetMaxCents() != null
                && (req.budgetMinCents() <= 0 || req.budgetMinCents() > req.budgetMaxCents())) {
            throw Api.error(400, "VALIDATION_INVALID", "Budget requires 0 < min <= max");
        }
        jdbc.update("INSERT INTO user_preferences(user_id,allergens,preferred_categories,spice_preference,taste_preference,"
                        + "budget_min_cents,budget_max_cents,recommend_enabled) VALUES (?,?,?,?,?,?,?,?) "
                        + "ON DUPLICATE KEY UPDATE allergens=VALUES(allergens), preferred_categories=VALUES(preferred_categories),"
                        + " spice_preference=VALUES(spice_preference), taste_preference=VALUES(taste_preference),"
                        + " budget_min_cents=VALUES(budget_min_cents), budget_max_cents=VALUES(budget_max_cents),"
                        + " recommend_enabled=VALUES(recommend_enabled)",
                uid, Util.json(allergens), Util.json(categories), req.spicePreference(), req.tastePreference(),
                req.budgetMinCents(), req.budgetMaxCents(), Boolean.TRUE.equals(req.recommendEnabled()) ? 1 : 0);
        return getPreferences();
    }

    @GetMapping("/addresses")
    public Map<String, Object> listAddresses() {
        long uid = SecurityConfig.current().id();
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT id,address,last_used_at FROM addresses WHERE user_id=? ORDER BY last_used_at DESC, id DESC", uid);
        List<Map<String, Object>> out = new ArrayList<>();
        for (Map<String, Object> r : rows) {
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("id", r.get("id"));
            m.put("address", r.get("address"));
            m.put("lastUsedAt", r.get("last_used_at"));
            out.add(m);
        }
        return Api.ok(out);
    }

    @PostMapping("/addresses")
    public ResponseEntity<Map<String, Object>> addAddress(@Valid @RequestBody Dtos.AddressReq req) {
        long uid = SecurityConfig.current().id();
        String address = req.address().trim();
        if (address.isEmpty()) throw Api.error(400, "VALIDATION_ADDRESS_LENGTH", "Address is required");
        try {
            jdbc.update("INSERT INTO addresses(user_id,address) VALUES (?,?)", uid, address);
        } catch (DuplicateKeyException ignored) {
            // unique (user_id,address): return existing
        }
        Long id = jdbc.queryForObject("SELECT id FROM addresses WHERE user_id=? AND address=?", Long.class, uid, address);
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("id", id);
        data.put("address", address);
        return ResponseEntity.status(HttpStatus.CREATED).body(Api.ok(data));
    }

    @DeleteMapping("/addresses/{id}")
    public Map<String, Object> deleteAddress(@PathVariable long id) {
        long uid = SecurityConfig.current().id();
        int n = jdbc.update("DELETE FROM addresses WHERE id=? AND user_id=?", id, uid);
        if (n == 0) throw Api.error(404, "NOT_FOUND", "Address not found");
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("deleted", true);
        return Api.ok(data);
    }
}

package com.webox.realtime;

import com.webox.common.Util;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.concurrent.CopyOnWriteArrayList;

@Component
public class SseHub {
    private static final Logger log = LoggerFactory.getLogger(SseHub.class);
    private final List<Entry> emitters = new CopyOnWriteArrayList<>();
    private final JdbcTemplate jdbc;

    public SseHub(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    private record Entry(SseEmitter emitter, LocalDate date) {}

    public SseEmitter subscribe(LocalDate date) {
        SseEmitter emitter = new SseEmitter(0L);
        Entry entry = new Entry(emitter, date);
        emitter.onCompletion(() -> emitters.remove(entry));
        emitter.onTimeout(() -> { emitters.remove(entry); emitter.complete(); });
        emitter.onError(e -> emitters.remove(entry));
        emitters.add(entry);
        try {
            emitter.send(SseEmitter.event().retry(3000L).name("snapshot").data(Util.json(snapshot(date))));
        } catch (Exception e) {
            emitters.remove(entry);
            emitter.completeWithError(e);
        }
        log.info("SSE subscriber added, active={}", emitters.size());
        return emitter;
    }

    public List<Map<String, Object>> snapshot(LocalDate date) {
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT s.dish_id, s.total_qty-s.reserved_qty-s.sold_qty AS available FROM dish_daily_stock s "
                        + "JOIN daily_menu m ON m.dish_id=s.dish_id AND m.serve_date=s.serve_date "
                        + "JOIN dishes d ON d.id=s.dish_id AND d.status='ON_SHELF' "
                        + "WHERE s.serve_date=? AND m.publish_status='PUBLISHED' ORDER BY s.dish_id", date);
        List<Map<String, Object>> out = new ArrayList<>();
        for (Map<String, Object> r : rows) {
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("dishId", r.get("dish_id"));
            m.put("available", Math.max(0, Util.intVal(r.get("available"))));
            out.add(m);
        }
        return out;
    }

    public void publishStock(long dishId, int available) {
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("dishId", dishId);
        data.put("available", Math.max(0, available));
        for (Entry e : emitters) {
            try {
                e.emitter().send(SseEmitter.event().retry(3000L).name("stock").data(Util.json(data)));
            } catch (Exception ex) {
                emitters.remove(e);
                try { e.emitter().complete(); } catch (Exception ignored) {}
            }
        }
    }

    @Scheduled(fixedDelay = 15000)
    public void heartbeat() {
        for (Entry e : emitters) {
            try {
                e.emitter().send(SseEmitter.event().comment("ping"));
            } catch (Exception ex) {
                emitters.remove(e);
            }
        }
    }

    public int activeConnections() { return emitters.size(); }
}

package com.webox.realtime;

import org.springframework.stereotype.Component;

import java.security.SecureRandom;
import java.util.Base64;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

@Component
public class TicketStore {
    private static final SecureRandom RANDOM = new SecureRandom();
    private final Map<String, Ticket> tickets = new ConcurrentHashMap<>();

    private static final class Ticket {
        final long userId;
        final String ip;
        final long expiresAt;
        final int[] uses = {0};
        Ticket(long userId, String ip, long expiresAt) { this.userId = userId; this.ip = ip; this.expiresAt = expiresAt; }
    }

    public String issue(long userId, String ip) {
        byte[] r = new byte[32];
        RANDOM.nextBytes(r);
        String t = Base64.getUrlEncoder().withoutPadding().encodeToString(r);
        tickets.put(t, new Ticket(userId, ip, System.currentTimeMillis() + 60_000));
        tickets.entrySet().removeIf(e -> e.getValue().expiresAt < System.currentTimeMillis());
        return t;
    }

    /** Returns userId or -1 when the ticket is invalid/expired/over-used. */
    public long redeem(String ticket, String ip) {
        Ticket t = tickets.get(ticket);
        if (t == null) return -1;
        synchronized (t) {
            if (t.expiresAt < System.currentTimeMillis()) { tickets.remove(ticket); return -1; }
            if (t.ip != null && ip != null && !t.ip.equals(ip)) return -1;
            if (t.uses[0] >= 3) { tickets.remove(ticket); return -1; }
            t.uses[0]++;
            return t.userId;
        }
    }
}

package com.webox.catalog;

import com.github.benmanes.caffeine.cache.Cache;
import com.webox.common.Api;
import com.webox.common.RequestContext;
import com.webox.common.Util;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;

import java.time.LocalDate;
import java.util.ArrayList;
import java.util.Comparator;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

@Service
public class MenuService {
    private final JdbcTemplate jdbc;
    private final Cache<String, Object> cache;

    public MenuService(JdbcTemplate jdbc, Cache<String, Object> menuCache) {
        this.jdbc = jdbc;
        this.cache = menuCache;
    }

    public void invalidate() { cache.invalidateAll(); }

    @SuppressWarnings("unchecked")
    private List<Map<String, Object>> staticDishes(LocalDate date) {
        String key = "dishes:" + date;
        Object cached = cache.getIfPresent(key);
        if (cached != null) return (List<Map<String, Object>>) cached;
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT d.id, d.name, d.description, d.price_cents, d.category, d.spice_level, d.image_url, "
                        + "EXISTS(SELECT 1 FROM dish_option_groups g WHERE g.dish_id=d.id) AS has_options, "
                        + "EXISTS(SELECT 1 FROM dish_option_groups g WHERE g.dish_id=d.id AND g.required=1) AS has_required_options "
                        + "FROM daily_menu m JOIN dishes d ON d.id=m.dish_id "
                        + "WHERE m.serve_date=? AND m.publish_status='PUBLISHED' AND d.status='ON_SHELF' ORDER BY d.name", date);
        cache.put(key, rows);
        return rows;
    }

    public Map<String, Object> list(String dateStr, int page, int size, String categories, String search, String sort) {
        Util.validatePage(page, size);
        LocalDate date = dateStr == null || dateStr.isBlank() ? RequestContext.today() : Util.parseDate(dateStr, "VALIDATION_INVALID");
        List<String> cats = new ArrayList<>();
        if (categories != null && !categories.isBlank()) {
            for (String c : categories.split(",")) {
                String t = c.trim();
                if (!t.isEmpty() && !Util.CATEGORIES.contains(t)) {
                    throw Api.error(400, "VALIDATION_CATEGORY", "Invalid category: " + t);
                }
                if (!t.isEmpty()) cats.add(t);
            }
        }
        if (search != null && search.length() > 50) {
            throw Api.error(400, "VALIDATION_SEARCH_LENGTH", "Search must be at most 50 characters");
        }
        String needle = search == null ? "" : search.trim().toLowerCase();

        Map<Long, Integer> available = availableMap(date);
        Map<Long, Map<String, Object>> prefs = preferenceContext();
        List<String> preferredCats = (List<String>) prefs.get("categories").get("categories");
        String spicePref = (String) prefs.get("categories").get("spice");
        boolean recommend = (Boolean) prefs.get("categories").get("enabled");

        List<Map<String, Object>> items = new ArrayList<>();
        for (Map<String, Object> d : staticDishes(date)) {
            String category = String.valueOf(d.get("category"));
            String name = String.valueOf(d.get("name"));
            String description = String.valueOf(d.get("description"));
            if (!cats.isEmpty() && !cats.contains(category)) continue;
            if (!needle.isEmpty() && !name.toLowerCase().contains(needle) && !description.toLowerCase().contains(needle)) continue;
            int qty = available.getOrDefault(((Number) d.get("id")).longValue(), 0);
            boolean forYou = recommend && (preferredCats.contains(category)
                    || (spicePref != null && spicePref.equals(String.valueOf(d.get("spice_level")))));
            Map<String, Object> m = new LinkedHashMap<>();
            long dishId = ((Number) d.get("id")).longValue();
            long price = Util.cents(d.get("price_cents"));
            m.put("dishId", dishId);
            m.put("name", name);
            m.put("description", description);
            m.put("priceCents", price);
            m.put("priceDisplay", Util.money(price));
            m.put("category", category);
            m.put("spiceLevel", d.get("spice_level"));
            m.put("imageUrl", d.get("image_url"));
            m.put("available", qty > 0);
            m.put("availableQty", qty);
            m.put("lowStock", qty > 0 && qty <= 3);
            m.put("soldOut", qty == 0);
            m.put("hasOptions", Util.intVal(d.get("has_options")) == 1);
            m.put("hasRequiredOptions", Util.intVal(d.get("has_required_options")) == 1);
            m.put("forYou", forYou);
            items.add(m);
        }
        if ("for-you".equals(sort)) {
            items.sort(Comparator.comparing((Map<String, Object> m) -> Boolean.TRUE.equals(m.get("forYou")) ? 0 : 1)
                    .thenComparing(m -> String.valueOf(m.get("name"))));
        } else {
            items.sort(Comparator.comparing(m -> String.valueOf(m.get("name"))));
        }
        int total = items.size();
        int from = Math.min((page - 1) * size, total);
        int to = Math.min(from + size, total);
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("items", items.subList(from, to));
        data.put("page", page);
        data.put("size", size);
        data.put("total", total);
        return data;
    }

    private Map<Long, Integer> availableMap(LocalDate date) {
        Map<Long, Integer> out = new HashMap<>();
        for (Map<String, Object> r : jdbc.queryForList(
                "SELECT dish_id, total_qty-reserved_qty-sold_qty AS available FROM dish_daily_stock WHERE serve_date=?", date)) {
            out.put(((Number) r.get("dish_id")).longValue(), Math.max(0, Util.intVal(r.get("available"))));
        }
        return out;
    }

    @SuppressWarnings("unchecked")
    private Map<String, Map<String, Object>> preferenceContext() {
        long uid = 0;
        try { uid = com.webox.config.SecurityConfig.current().id(); } catch (Exception ignored) {}
        List<Map<String, Object>> rows = jdbc.queryForList("SELECT * FROM user_preferences WHERE user_id=?", uid);
        Map<String, Object> ctx = new LinkedHashMap<>();
        if (rows.isEmpty()) {
            ctx.put("categories", List.of());
            ctx.put("spice", null);
            ctx.put("enabled", false);
        } else {
            Map<String, Object> r = rows.get(0);
            ctx.put("categories", Util.parseList((String) r.get("preferred_categories")));
            ctx.put("spice", r.get("spice_preference"));
            ctx.put("enabled", ((Number) r.get("recommend_enabled")).intValue() == 1);
        }
        Map<String, Map<String, Object>> wrapper = new LinkedHashMap<>();
        wrapper.put("categories", ctx);
        return wrapper;
    }

    public Map<String, Object> detail(long dishId) {
        LocalDate today = RequestContext.today();
        List<Map<String, Object>> rows = jdbc.queryForList(
                "SELECT d.* FROM dishes d JOIN daily_menu m ON m.dish_id=d.id AND m.serve_date=? AND m.publish_status='PUBLISHED' "
                        + "WHERE d.id=? AND d.status='ON_SHELF'", today, dishId);
        if (rows.isEmpty()) throw Api.error(404, "DISH_NOT_FOUND", "Dish not found on today's menu");
        Map<String, Object> d = rows.get(0);
        int qty = 0;
        List<Map<String, Object>> stock = jdbc.queryForList(
                "SELECT total_qty-reserved_qty-sold_qty AS available FROM dish_daily_stock WHERE dish_id=? AND serve_date=?",
                dishId, today);
        if (!stock.isEmpty()) qty = Math.max(0, Util.intVal(stock.get(0).get("available")));
        long price = Util.cents(d.get("price_cents"));
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("dishId", d.get("id"));
        data.put("name", d.get("name"));
        data.put("description", d.get("description"));
        data.put("priceCents", price);
        data.put("priceDisplay", Util.money(price));
        data.put("category", d.get("category"));
        data.put("protein", d.get("protein"));
        data.put("allergens", Util.parseList((String) d.get("allergens")));
        data.put("spiceLevel", d.get("spice_level"));
        data.put("imageUrl", d.get("image_url"));
        data.put("available", qty > 0);
        data.put("availableQty", qty);
        data.put("optionGroups", optionGroups(dishId));
        return data;
    }

    public List<Map<String, Object>> optionGroups(long dishId) {
        List<Map<String, Object>> groups = jdbc.queryForList(
                "SELECT id,name,required,min_select,max_select FROM dish_option_groups WHERE dish_id=? ORDER BY sort_order,id", dishId);
        List<Map<String, Object>> out = new ArrayList<>();
        for (Map<String, Object> g : groups) {
            Map<String, Object> m = new LinkedHashMap<>();
            m.put("groupId", g.get("id"));
            m.put("name", g.get("name"));
            m.put("required", ((Number) g.get("required")).intValue() == 1);
            m.put("minSelect", g.get("min_select"));
            m.put("maxSelect", g.get("max_select"));
            List<Map<String, Object>> opts = jdbc.queryForList(
                    "SELECT id,name,price_delta_cents FROM dish_options WHERE group_id=? ORDER BY sort_order,id", g.get("id"));
            List<Map<String, Object>> options = new ArrayList<>();
            for (Map<String, Object> o : opts) {
                Map<String, Object> om = new LinkedHashMap<>();
                om.put("optionId", o.get("id"));
                om.put("name", o.get("name"));
                om.put("priceDeltaCents", Util.cents(o.get("price_delta_cents")));
                options.add(om);
            }
            m.put("options", options);
            out.add(m);
        }
        return out;
    }

    public Map<String, Object> filters() {
        Object cached = cache.getIfPresent("filters");
        if (cached != null) return (Map<String, Object>) cached;
        Map<String, Object> data = new LinkedHashMap<>();
        data.put("categories", Util.CATEGORIES);
        data.put("spiceLevels", Util.SPICE);
        data.put("allergens", Util.ALLERGENS);
        List<Map<String, Object>> dates = new ArrayList<>();
        LocalDate today = RequestContext.today();
        for (int i = 0; i < 3; i++) {
            LocalDate d = today.plusDays(i);
            Integer count = jdbc.queryForObject(
                    "SELECT COUNT(*) FROM daily_menu WHERE serve_date=? AND publish_status='PUBLISHED'", Integer.class, d);
            Map<String, Object> dm = new LinkedHashMap<>();
            dm.put("date", d.toString());
            dm.put("published", count != null && count > 0);
            dates.add(dm);
        }
        data.put("dates", dates);
        cache.put("filters", data);
        return data;
    }
}

